const root = ReactDOM.createRoot(document.querySelector('#root'));

const items = [
  { id: 'shirt', name: '셔츠' },
  { id: 'hat', name: '모자' },
  { id: 'socks', name: '양말' },
];

const List = ({ list }) => (
  <ul className="list">
    {list.map((item, index) => (
      <li className="item">
        <span className="item__name">{item.name}</span>
        <input className="item__memo" placeholder="메모" />
      </li>
    ))}
  </ul>
);

root.render(<List list={items} />);

// 5초 뒤에 순서를 뒤집어 다시 그립니다. 그 전에 첫 줄의 메모 칸에 무언가 적어 두세요.
setTimeout(() => {
  console.log('순서를 바꿉니다');
  root.render(<List list={[items[2], items[1], items[0]]} />);
}, 5000);

